(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-3-nose-sinuses-vignettes"]={"title":"Nose and Paranasal Sinuses Vignettes 1 — CMS I Exam 3","category":"Clinical Medicine and Surgery I","exam":"Exam 3","sem":"fall-2026","questions":[{"q":"A 39-year-old woman with nasal polyps is started on medical treatment. Which combination is used?","choices":["Oral antibiotics and antifungals","Nasal packing","Long-term systemic antibiotics","Oseltamivir","Antihistamine, leukotriene, steroid"],"answer":4,"exp":"Correct, with ipratropium, immunotherapy and cautious decongestant use. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 65"},{"q":"A 62-year-old woman has had sinus symptoms for twelve days without any improvement, with persistent purulent discharge. What does the duration alone indicate?","choices":["It confirms a fungal cause","It indicates chronic sinusitis","It indicates allergic disease","It suggests bacterial infection","It confirms a viral cause"],"answer":3,"exp":"Correct &mdash; one of the named features. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 16"},{"q":"A 45-year-old woman with nasal polyps and asthma develops severe bronchospasm after taking aspirin. What does this combination represent?","choices":["Allergic fungal sinusitis","Cystic fibrosis presenting late","Churg-Strauss syndrome","Aspirin-exacerbated respiratory disease","Anaphylaxis to aspirin"],"answer":3,"exp":"Correct &mdash; polyps, asthma and aspirin sensitivity. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 59"},{"q":"A 30-year-old woman with seasonal allergies insists she gets sinus infections every spring. How should the relationship be explained?","choices":["It creates the environment for infection","Allergy directly infects the sinuses","The two are unrelated","Allergy protects against sinus infection","Only children show this relationship"],"answer":0,"exp":"Correct &mdash; allergy does not cause an inflammation per se. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 13"},{"q":"A 4-year-old boy is suspected of having a bead in his nose. What establishes the diagnosis?","choices":["Computed tomography","Plain radiography","Culture of the discharge","A trial of antibiotics","Direct visualisation"],"answer":4,"exp":"Correct &mdash; imaging is rarely needed. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 54"},{"q":"A 58-year-old man on chemotherapy develops facial pain, fever and black discharge from the nose. Which cause must be considered?","choices":["Allergic rhinitis","A nasal foreign body","Nasal polyps","A fungal infection","Ordinary viral rhinosinusitis"],"answer":3,"exp":"Correct. Immunocompromised patients get Rhizopus, Mucor and occasionally Aspergillus &mdash; and black discharge suggests fungus. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 12"},{"q":"A 40-year-old woman with a septal perforation from prolonged intranasal steroid use asks whether it can heal. What should she be told?","choices":["It requires lifelong antibiotics","It will heal regardless of whether the steroid continues","It requires nasal packing","Treat the cause; else septoplasty","It will never heal and surgery is immediate"],"answer":3,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 40"},{"q":"A 35-year-old man has just had nasal packing for epistaxis. What must he be told to avoid?","choices":["Drinking cold fluids","Sleeping propped up","Using a cold compress","Talking","Blowing his nose"],"answer":4,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 51"},{"q":"A 29-year-old man has years of one-sided nasal blockage, snoring and recurrent nosebleeds from the same side. Examination shows one nasal passage clearly narrower. What is the most likely diagnosis?","choices":["Allergic rhinitis","Nasopharyngeal carcinoma","Deviated septum","Nasal polyps","Septal perforation"],"answer":2,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 32"},{"q":"A 9-year-old boy has recurrent nosebleeds from the front of the left nostril, easily controlled by pinching. What is the likely source?","choices":["The greater palatine artery","The frontal sinus","Kiesselbach's plexus","The sphenopalatine artery","The internal carotid artery"],"answer":2,"exp":"Correct &mdash; the anterior septal watershed, and the source of about ninety per cent of nosebleeds. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 46"},{"q":"A 48-year-old man asks how his doctor decided his sinusitis was chronic. What is the threshold?","choices":["Twelve weeks","Four weeks","Two weeks","Six months","One year"],"answer":0,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 28"},{"q":"A 31-year-old woman has four days of nasal congestion, facial pressure and clear discharge after a cold. She is afebrile and the pressure is not reproduced by pressing over her cheeks. What is the appropriate management?","choices":["Symptomatic treatment alone","Amoxicillin with clavulanate now","Sinus radiography","Immediate ENT referral","Oral corticosteroids"],"answer":0,"exp":"Correct. Most acute rhinosinusitis is viral and improves without antibiotics. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 22"},{"q":"A 52-year-old immunocompetent woman has unilateral sinus disease with a fungus ball on imaging and no bony erosion. How is she treated?","choices":["Surgery plus antifungals","Antifungals alone","Antibiotics","Observation","Surgery alone"],"answer":4,"exp":"Correct. Antifungals are added only if bony erosion has occurred. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 30"},{"q":"A 37-year-old man with a first episode of sinus symptoms asks for a scan to find out if he needs antibiotics. What should he be told?","choices":["A blood test will settle it","No imaging can separate them","A plain radiograph will settle it","Computed tomography will settle it","A nasal swab will settle it"],"answer":1,"exp":"Correct, and routine radiography is discouraged. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 21"},{"q":"A 68-year-old man on warfarin has heavy bleeding with blood running down the back of his throat, and it does not stop with anterior pressure. What does this suggest and what is the concern?","choices":["Nasal polyps","A posterior bleed, with a risk of aspiration","An anterior bleed that needs more pressure","Allergic rhinitis","A nasal foreign body"],"answer":1,"exp":"Correct &mdash; posterior bleeds carry higher risk from aspiration and subsequent infection. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 45"},{"q":"A 41-year-old woman has had constant nasal congestion and sinus pressure for five months, with intermittent flares. What is the most likely diagnosis?","choices":["Acute sinusitis","Allergic rhinitis","Nasal foreign body","Deviated septum","Chronic sinusitis"],"answer":4,"exp":"Correct &mdash; more than twelve weeks, from impaired mucociliary clearance causing repeated infection. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 28"},{"q":"A 48-year-old man from southern China has months of headache, double vision, numbness of the left cheek and a firm neck mass. What is the appropriate step?","choices":["Arrange allergy skin testing","Reassure and review in three months","Refer to ENT for endoscopic guided biopsy","Treat as chronic sinusitis with antibiotics","Start an antihistamine"],"answer":2,"exp":"Correct &mdash; this is the nasopharyngeal carcinoma picture. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 70"},{"q":"A 47-year-old woman asks whether her green nasal discharge proves she needs antibiotics. What should she be told?","choices":["Green means blood is present","Yellow or green is the least helpful colour","Green always means bacterial infection","Green always means viral infection","Green means a fungal cause"],"answer":1,"exp":"Correct. Colour barely helps; only black, rust or pure clear carry any signal. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 19"},{"q":"A 7-year-old boy is found to have multiple benign nasal polyps. What must be arranged?","choices":["A trial of antibiotics","Cystic fibrosis and asthma","Reassurance and review in a year","Immediate surgery alone","Allergy testing only"],"answer":1,"exp":"Correct &mdash; every child with multiple polyps. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 61"},{"q":"A 36-year-old man being treated for sinusitis returns with double vision and swelling around the right eye. What is the priority?","choices":["Urgent computed tomography","Change the antibiotic and review in a week","Add an intranasal steroid","Reassure &mdash; this is expected","Arrange allergy skin testing"],"answer":0,"exp":"Correct. Diplopia and periorbital swelling are named urgent features. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 21"},{"q":"A 45-year-old man with chronic bacterial sinusitis has failed several short antibiotic courses. What is the appropriate regimen and referral?","choices":["Antihistamines alone","No treatment &mdash; await spontaneous resolution","Steroids, antibiotics and ENT referral","A three-day course of azithromycin","Topical antifungals alone"],"answer":2,"exp":"Correct, with allergy skin testing as well. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 29"},{"q":"A 46-year-old man has a septal perforation, and also reports haemoptysis and blood in his urine. Which diagnosis should be considered?","choices":["Allergic rhinitis","Chronic sinusitis","Granulomatosis with polyangiitis","Cocaine use","Secondary syphilis, long treated"],"answer":2,"exp":"Correct &mdash; a vascular autoimmune disease named as a rare cause of nasal deformity. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 37"},{"q":"A 51-year-old man is diagnosed with nasopharyngeal carcinoma. Which exposures are associated with it?","choices":["Epstein-Barr virus and smoking","Cold water exposure","Aminoglycoside use","Repeated air travel","Intranasal steroid use"],"answer":0,"exp":"Correct, along with high-salt diets. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 69"},{"q":"A 47-year-old man with allergic rhinitis also has poorly controlled hypertension. Which treatment needs particular caution?","choices":["Non-drowsy antihistamines","Leukotriene inhibitors","Intranasal ipratropium","Immunotherapy","Decongestants"],"answer":4,"exp":"Correct &mdash; caution with chronic use and with high blood pressure. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 68"},{"q":"A 33-year-old man with allergic rhinitis is frustrated that one medicine has not fixed it. What should he be told?","choices":["He should stop all treatment for a month","Most need two or more medicines","One medicine should always be enough","Surgery is the usual answer","Antibiotics will help"],"answer":1,"exp":"Correct &mdash; there are multiple pathways involved. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 68"},{"q":"A 44-year-old man had a cold that improved by day four, then worsened on day seven with right-sided facial pain, purulent discharge and a temperature of 38.5 degrees Celsius. Pressing over the right maxilla reproduces his pain. What should be done?","choices":["Prescribe an antifungal","Reassure and review in two weeks","Start amoxicillin with clavulanate","Continue symptomatic treatment alone","Arrange sinus radiography first"],"answer":2,"exp":"Correct. Double worsening, unilateral pain reproduced on palpation and fever together point bacterial. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 23"},{"q":"A 24-year-old woman has swelling and tenderness confined to the bony bridge after a fall. She breathes freely through each nostril, the nose is straight, and there is no septal haematoma. What imaging is required?","choices":["Computed tomography of the face","Magnetic resonance imaging","Ultrasound of the nose","None","Plain nasal radiographs"],"answer":3,"exp":"Correct &mdash; all four criteria are met. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 57"},{"q":"An 8-year-old girl with multiple nasal polyps is being screened for cystic fibrosis. Which test is used?","choices":["The chloride sweat test","Serum IgE","A nasal smear for eosinophils","Computed tomography of the sinuses","Nasal culture"],"answer":0,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 64"},{"q":"A 58-year-old woman continues bleeding after ten minutes of correct pressure and oxymetazoline. What comes next?","choices":["Discharge with reassurance","Packing or a balloon catheter","Repeat the same pressure for another hour","Oral tranexamic acid alone","Immediate surgery"],"answer":1,"exp":"Correct, alongside thrombogenic foams and gels. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 51"},{"q":"A 44-year-old man with chronic sinusitis is having his treatment planned. What should guide the choice of antibiotic?","choices":["Blood cultures","Serum IgE alone","Empirical choice with no sampling","Endoscopic tissue for culture","A nasal swab from the anterior nares"],"answer":3,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 28"}]};
